import {expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
import {randomUUID,createHash} from 'node:crypto';
import {invertCube} from './lut-ui.mjs';
import {imageDigest} from './text-ui.mjs';
export async function exerciseLutConvenience(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh,pack='Dropped-'+randomUUID().slice(0,8),name=pack+'.cube',cube='# Input: S-Log3\n'+invertCube(pack),hash=createHash('sha256').update(cube).digest('hex'),panel=page.locator('.lut-panel'),photo=page.locator('.edit-image img'),sourceName=await photo.getAttribute('alt'),before=await imageDigest(photo);
 await page.evaluate(hash=>{const Native=window.Worker;window.__thumbFailures=0;window.Worker=class extends Native{constructor(url,options){super(url,options);if(String(url).includes('lut-preview-worker')){const send=this.postMessage.bind(this);this.postMessage=(data,...rest)=>{if(data.hash===hash&&!window.__thumbFailures){window.__thumbFailures++;queueMicrotask(()=>this.dispatchEvent(new MessageEvent('message',{data:{id:data.id,error:'LUT preview unavailable.'}})));return;}return send(data,...rest);};}}};},hash);
 await panel.locator(':scope>summary').click();await panel.getByRole('searchbox').fill(pack);
 await panel.evaluate((el,{pack,name,cube})=>{
  const f=(name,text)=>({name,isFile:true,isDirectory:false,file:ok=>setTimeout(()=>ok(new File([text],name)),0)}),dir=(name,children)=>({name,isFile:false,isDirectory:true,createReader(){let n=0;return {readEntries:ok=>setTimeout(()=>ok(children.slice(n,n+=1)),0)};}}),root=dir(pack,[dir('Cinema',[f(name,cube)]),dir('Notes',[f('Readme.txt','synthetic')])]),data=new DataTransfer(),item=data.items.add(new File(['directory'],pack));const proto=DataTransferItem.prototype,originalEntry=proto.webkitGetAsEntry;proto.webkitGetAsEntry=function(){return this.getAsFile()?.name===pack?root:originalEntry.call(this);};window.__restoreLutDrop=()=>{proto.webkitGetAsEntry=originalEntry;};window.__lutDropData=data;el.dispatchEvent(new DragEvent('dragenter',{dataTransfer:data,bubbles:true,cancelable:true}));
 },{pack,name,cube});
 await expect(panel).toHaveClass(/lut-drop-active/);await panel.evaluate(el=>{el.dispatchEvent(new DragEvent('drop',{dataTransfer:window.__lutDropData,bubbles:true,cancelable:true}));window.__restoreLutDrop();delete window.__restoreLutDrop;delete window.__lutDropData;});
 await expect(panel.locator('.lut-import-report')).toContainText(t('新增 1','Added 1'));await expect(panel.locator('.lut-import-report')).toContainText(t('非 CUBE 文件 1','Non-CUBE files 1'));await expect(panel).not.toHaveClass(/lut-drop-active/);
 const choice=panel.getByRole('button',{name:t('应用 LUT ','Apply LUT ')+name,exact:true}),row=panel.locator('[data-lut="'+hash+'"]');await choice.scrollIntoViewIfNeeded();await expect(row.getByRole('button',{name:t('重试缩略图','Retry thumbnail')})).toBeVisible();expect(await imageDigest(photo)).toBe(before);expect(await page.evaluate(()=>window.__thumbFailures)).toBe(1);
 await row.getByRole('button',{name:t('重试缩略图','Retry thumbnail')}).click();await expect(choice.locator('img')).toBeVisible();await expect(row.locator('.lut-thumbnail-error')).toHaveCount(0);
 const expand=panel.getByRole('button',{name:t('展开全部目录','Expand all folders'),exact:true}),collapse=panel.getByRole('button',{name:t('收起全部目录','Collapse all folders'),exact:true}),branch=panel.getByRole('button',{name:t('展开或收起目录 ','Expand or collapse folder ')+pack,exact:true});await expand.click();await expect(branch).toHaveAttribute('aria-expanded','true');await collapse.click();await expect(branch).toHaveCount(0);await expand.click();await branch.click();await expect(branch).toHaveAttribute('aria-expanded','false');expect(await imageDigest(photo)).toBe(before);
 await choice.click();await expect.poll(()=>imageDigest(photo)).not.toBe(before);const graded=await imageDigest(photo),source=panel.locator('.lut-source-info');await expect(source).toContainText(pack+' / Cinema');await expect(source).toContainText('Input: S-Log3');
 const download=page.waitForEvent('download');await source.getByRole('button',{name:t('取出 CUBE 文件','Save CUBE file'),exact:true}).click();const result=await download;expect(result.suggestedFilename()).toBe(name);expect(readFileSync(await result.path(),'utf8')).toBe(cube);expect(await imageDigest(photo)).toBe(graded);
 const save=page.getByRole('button',{name:new RegExp('^'+t('保存编辑','Save edits'))});await save.click();await expect(save).toBeEnabled();await page.goto(new URL(page.url()).port==='4185'?'/#/tools/edit':'/tools/darkroom');await expect(page).not.toHaveURL(/[?&]photo=/);await expect(page.locator('.edit-records')).toBeVisible();await page.reload();await page.locator('.edit-records>div>button').filter({hasText:sourceName}).first().click();await expect.poll(()=>imageDigest(photo)).toBe(graded);await panel.locator(':scope>summary').click();await panel.getByRole('searchbox').fill(pack);await expect(branch).toHaveAttribute('aria-expanded','false');await expect(source).toContainText(pack+' / Cinema');await choice.scrollIntoViewIfNeeded();await expect(choice.locator('img')).toBeVisible();await page.screenshot({path:info.outputPath('lut-convenience.png'),fullPage:true});if(lang==='en')expect(await panel.innerText()).not.toMatch(/[\u3400-\u9fff]/);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
}
